        var prInfo = file_read({ path: prInfoPath }) || '';
        var branchMatch = prInfo.match(/\*\*Branch\*\*:\s*`([^`]+)`/);
        if (branchMatch) expectedBranch = branchMatch[1].trim();
    } catch (e) {
