    const status = prHelper.readStagedDiffStat(cmd, workingDir);

    var hasChanges = false;
    if (status.trim()) {
        const commitMsg = stripCiSkipTokens(configLoader.formatTemplate(config.formats.commitMessage.rework, {ticketKey: ticketKey}));
