            replyRef.indexOf('/') !== -1 ||
            replyRef.indexOf('.md') !== -1;
        if (looksLikePath) {
            const fileContent = outputFiles.readOutputFile(replyRef, outputOptions);
            if (fileContent && fileContent.trim()) {
                return fileContent.trim();
            }
        }
        return replyRef;
    }

