    var outputFile = '.dmtools-session-output.log';

    var snapshotTimestamp = new Date().toISOString();
    var snapshotHeader = '=== ⏱️ TIMER SESSION SNAPSHOT START (saved at ' + snapshotTimestamp + ') ===\n' +
