// gh-798: the in-flight-leg exclusion for update_branch. A rework/review
// ai-teammate leg dispatched with workflowRef={branch} lands on the PR
// head (its run head_sha IS the PR head), so an ACTIVE run of the leg
// workflow on the head rollup means the head is owned mid-run — the
// silent refresh must defer (the leg's timer pushes WIP auto-saves to
// that ref; a merged-in base rejects them non-fast-forward). hasActiveHeadRun
// semantics (any queued/in_progress/waiting/pending run), narrowed to the
// leg workflow path so unrelated CI never blocks freshness, plus the same
// stale-zombie window the dispatch guard applies (a leg stuck 'queued' for
// hours ages out). Takes the pre-fetched head rollup (headWorkflowRunsSafe).
function hasActiveLegRun(runs, workflowFile) {
    var suffix = '/' + String(workflowFile || 'ai-teammate.yml');
    return (runs || []).some(function (r) {
        if (!r) return false;
        var status = r.status;
        if (status !== 'queued' && status !== 'in_progress' &&
            status !== 'waiting' && status !== 'pending') return false;
        if (status !== 'in_progress' && isStaleNonRunningWorkflowRun(r, status)) return false;
        var p = String(r.path || '');
        return p.length >= suffix.length &&
            p.slice(p.length - suffix.length) === suffix;
    });
}
