        '! [rejected]        HEAD -> ai/gh-1415 (non-fast-forward)\n' +
        'hint: Updates were rejected because the tip of your current branch is behind';

    function makeCmd(script) {
        var calls = [];
        var cmd = function(command) {
            calls.push(command);
            return script(command);
        };
        cmd.calls = calls;
