        command: 'gh api "repos/' + repoInfo.owner + '/' + repoInfo.repo +
                 '/actions/runs?head_sha=' + headSha + '&per_page=50"'
    });
    var runs = mcpParse((res || {}).output || (res || {}).stdout || res);
    return (runs && runs.workflow_runs) || [];
}

